    private static int NearestShade(int[] shades, int shade)
    {
        int best = 0;
        for (int i = 1; i < shades.Length; ++i) if (Math.Abs(shades[i] - shade) < Math.Abs(shades[best] - shade)) best = i;
        return best;
    }
    private static readonly int[] ShadeNumbers = [50, 100, 200, 300, 400, 500, 600, 700, 800, 900], AccentNumbers = [100, 200, 400, 700];
    /// <summary>A palette colour: <paramref name="shade"/> 50, 100, 200, ..., 900 (another number gives the nearest).</summary>
    public static Vec4 MaterialColor(MaterialHue hue, int shade = 500) => ColorFromHex(MaterialShades[(int)hue, NearestShade(ShadeNumbers, shade)]);
    /// <summary>An accent, A100 to A700; brown, grey and blue grey have none, and give their plain shade of the number.</summary>
    public static Vec4 MaterialAccent(MaterialHue hue, int shade = 200)
    {
        int i = NearestShade(AccentNumbers, shade);
        uint accent = MaterialAccents[(int)hue, i];
        return accent != 0 ? ColorFromHex(accent) : MaterialColor(hue, AccentNumbers[i]);
    }
